<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoice {{ $document['orderNumber'] }}</title><style>body{font:14px/1.6 Arial,sans-serif;color:#171717;background:#f5f5f5;margin:0}main{max-width:850px;margin:32px auto;background:#fff;padding:48px;border:1px solid #ddd}header{display:flex;justify-content:space-between;border-bottom:1px solid #ddd;padding-bottom:25px}h1{margin:0}table{width:100%;border-collapse:collapse;margin:30px 0}th,td{text-align:left;padding:12px 8px;border-bottom:1px solid #eee}td:last-child,th:last-child{text-align:right}dl{margin-left:auto;max-width:310px}dl div{display:flex;justify-content:space-between}dd{margin:0}.actions{padding:16px;text-align:center}button{padding:10px 20px;border:1px solid #ddd;border-radius:6px;background:#fff;cursor:pointer}@media print{body{background:white}.actions{display:none}main{border:0;margin:0;padding:20px}}</style></head><body>
@php($money = fn($amount) => $document['currency'].' '.number_format($amount * ($document['currencyExchangeRate'] ?? 1), 2))
<div class="actions"><button onclick="window.print()">Print / Save PDF</button></div><main><header><div><h1>Invoice</h1><p>{{ $seller }}</p><strong>{{ $document['orderNumber'] }}</strong><div>{{ \Illuminate\Support\Carbon::parse($document['createdAt'])->format('d M Y') }}</div></div><div>Payment status: {{ str_replace('_', ' ', $document['paymentGatewayStatus']) }}</div></header><h3>Bill to</h3><div>{{ $document['customerName'] }}<br>{{ $document['customerEmail'] }}</div><table><thead><tr><th>Item</th><th>Quantity</th><th>Unit price</th><th>Amount</th></tr></thead><tbody>@foreach($document['items'] as $item)<tr><td>{{ $item['title'] }}<br><small>{{ $item['variantTitle'] }} · {{ $item['sku'] }}</small></td><td>{{ $item['quantity'] }}</td><td>{{ $money($item['price']) }}</td><td>{{ $money($item['price']*$item['quantity']) }}</td></tr>@endforeach</tbody></table><dl>@foreach(['Subtotal'=>'subtotal','Discount'=>'discountAmount','Shipping'=>'shippingAmount','Tax'=>'taxAmount','Total'=>'totalAmount'] as $label=>$key)<div><dt>{{ $label }}</dt><dd>{{ $money($document[$key] ?? 0) }}</dd></div>@endforeach</dl><p>Payment method: {{ $document['paymentGateway'] }}</p></main></body></html>
